# Check 3x3 regions that have a specific pattern

def analyze_3x3_patterns():
    patterns_found = []
    rows, cols = grid_np.shape

    for r in range(rows):
        for c in range(cols-2):
            sub = grid_np[r:r+3, c:c+3].flatten()
            # Count occurrences
            counts = np.bincount(sub, minlength=10)[:10]
            # Look for patterns - e.g., 3 center colors
            if 0 in sub and counts[3] == 3 or counts[9] == 3:
                patterns_found.append((r, c, sub.copy()))

    return patterns_found

