# Let me visualize the grid in ASCII format to understand the pattern better
grid_np = np.array(grid)

# Create a visual representation where each pixel is a small square
def visualize_grid(grid, cell_size=2):
    rows, cols = grid.shape
    result = []
    for r in range(rows):
        row_str = ""
        for c in range(cols):
            val = grid[r, c]
            if val == 0:
                row_str += "." * cell_size
            elif val == 5:
                row_str += "#" * cell_size  # Background
            elif val == 2:
                row_str += "@" * cell_size  # Yellow-like
            elif val == 3:
                row_str += "3" * cell_size  # Green-like
            elif val == 9:
                row_str += "9" * cell_size  # Maroon-like
            else:
                row_str += str(val) * cell_size
        result.append(row_str)
    return "\n".join(result)

print("=== Visual grid (3x cell size) ===")
print(visualize_grid(grid_np, 1))

